public class METCrossDockTransferOrderProcessor
{
    InventParameters inventParameter;
    InventTransferTable transferTable;
    METInventTransferTableExt metTransferTable;

}

Method.Source:
public NoYes isUnderBondItem(ItemId _itemId)
{
    NoYes ret = NoYes::No;
    METInventTable metInventTable;
    metTariffItemCodeBase metTariffItemCodeBase;

    select firstonly METTariffItemCodeBaseRecid from metInventTable
            where metInventTable.ItemId == _itemId
            exists join metTariffItemCodeBase
            where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid;

    ret = metInventTable.METTariffItemCodeBaseRecid ? NoYes::Yes : NoYes::No;

    return ret;
}

/// <summary>
/// Primarily used to create transfer order lines during substitution process. As the substitution will process each sales lines
/// </summary>
/// <param name = "_salesLine"></param>
public void CreateTransferOrderFromSalesLine(SalesLine _salesLine)
{
    SalesTable salesTable;
    METSalesTable metSalesTable;
    METSalesLine metSalesLine = _salesLine.metSalesLine();

    // Bug 225259: CB238 - NDC / Int xDock: D365 functional warehouse processing Liquor LE SO extraction and TO extraction LSE004 and LTE003 substitution issues
    // When called from subs, the record was not initialised
    inventParameter = InventParameters::find();

    select firstonly salesTable
        where salesTable.SalesId == _salesLine.SalesId
        join metSalesTable
        where metSalesTable.SalesTable == salesTable.RecId;

    ttsbegin;
    this.CreateTransferOrderLine(_salesLine, metSalesLine, salesTable, metSalesTable);
    ttscommit;
}

public static METCrossDockTransferOrderProcessor construct()
{
    return new METCrossDockTransferOrderProcessor();
}

public void findOrCreateTransferHeader(SalesLine _salesLine, METSalesLine _metSalesLine, SalesTable _salesTable, METSalesTable _metSalesTable)
{
    //InventTransferTable transferTable;
    //METInventTransferTableExt metTransferTable;

    NoYes underBond = this.isUnderBondItem(_salesLine.ItemId);

    InventLocationId fromWh = _metSalesLine.SupplyingWarehouse;
    InventLocationId toWh = _salesLine.inventDim().InventLocationId;

    select firstonly RecId from metTransferTable
        where metTransferTable.SalesId == _salesLine.SalesId
        && metTransferTable.UnderBond == underBond
        join transferTable
        where transferTable.RecId == metTransferTable.InventTransferTable
        // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
        // For allow backorders scenario, the previous TO will be received so need to create a new TO as per scenario
        && transferTable.TransferStatus == InventTransferStatus::Created
        && transferTable.InventLocationIdFrom == fromWh
        && transferTable.InventLocationIdTo == toWh;

    if(!metTransferTable)
    {
        transferTable.clear();
        transferTable.initValue();
        transferTable.TransferId = InventTransferTable::numberSeq().num();
        transferTable.InventLocationIdFrom = fromWh;
        transferTable.modifiedField(fieldNum(InventTransferTable, InventLocationIdFrom));
        transferTable.InventLocationIdTo = toWh;
        transferTable.modifiedField(fieldNum(InventTransferTable, InventLocationIdTo));
        transferTable.initFromAddress();
        transferTable.initToAddress();
        transferTable.ShipDate = _metSalesTable.SecondShipDate;
        transferTable.ReceiveDate = _salesTable.ShippingDateConfirmed;
        //Mark the Auto reservation to true if the Reserve items automatically flag is enabled or the sales order is an event order.
        transferTable.AutoReservation = (inventParameter.InventTransferAutoReservation || _metSalesTable.EventID != '');

        if (transferTable.validateWrite())
        {
            transferTable.insert();

            info(strFmt("@MET:ToCreated", transferTable.TransferId));
            //CB627_TMSEngineProcessingTOCreation

            TMSInventTransferTable  tmsTransferTable;
            TMSSalesTable           tmsSalesTable = TMSSalesTable::find(_salesTable.SalesId);

            tmsTransferTable.initFromInventTransferId(transferTable.TransferId);
            tmsTransferTable.setCarrierFields(_metSalesTable.SecondaryCarrierCode, _metSalesTable.SecondaryCarrierServiceCode);
            tmsTransferTable.insert();
        }
        else
        {
            throw error("@SCM:FailTransferOrder");
        }

        if (transferTable.RecId != 0)
        {
            metTransferTable.clear();
            metTransferTable.InventTransferTable = transferTable.RecId;

            metTransferTable.Route = _metSalesTable.SecondRoute;
            metTransferTable.StagingLane = _metSalesTable.StagingLaneId;
            metTransferTable.OrderSplitGroup = _metSalesTable.OrderSplitGroup;
            metTransferTable.WMSOrderType = _metSalesTable.WMSOrderType;
            metTransferTable.RouteIdentifier = _metSalesTable.OriginalSecondRouteIdentifier;

            metTransferTable.RouteStopNum = _metSalesTable.SecondRouteStopNum;
            metTransferTable.RouteStopIdentifier = _metSalesTable.OriginalSecondRouteStopIdentifier;

            metTransferTable.DeliveryInstructions = _metSalesTable.DeliveryInstructions;
            metTransferTable.SalesId = _salesLine.SalesId;
            metTransferTable.UnderBond = underBond;
            metTransferTable.TransferType = _metSalesTable.InternalCrossDockOrder == NoYes::Yes ? METCrossDockTransferType::CrossDock : METCrossDockTransferType::CSD;

            // 218457 - CB238 - Bug - Liquor extraction Internal Customer not getting updated - Start
            metTransferTable.InternalCustomer = _salesTable.CustAccount;
            // 218457 - CB238 - Bug - Liquor extraction Internal Customer not getting updated - End

            if (_metSalesTable.InternalCrossDockOrder == NoYes::Yes && 
                metTransferTable.TransferType ==  METCrossDockTransferType::CrossDock)
            {
                metTransferTable.StagingLane = _metSalesTable.SecondaryStagingLaneId;
                metTransferTable.Door = any2Str(_metSalesTable.SecondaryDoorNum);
            }
            metTransferTable.insert();
        }
    }
}

private void CreateTransferOrderLine(SalesLine _salesLine, METSalesLine _metSalesLine, SalesTable _salesTable, METSalesTable _metSalesTable)
{
    // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
    // get qtyReserved in inventory unit instead of sales unit then no conversion required
    //SalesQty qtyReserved = _salesLine.mcrSalesQtyReserved();
    InventQty qtyReserved = _salesLine.reservedPhysical();

    // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
    // Need to look at deliver remainder for back orders
    //if (qtyReserved < _salesLine.QtyOrdered)
    if (qtyReserved < _salesLine.RemainInventPhysical)
    {
        InventTransferLine transferLine;
        METInventTransferLine metTransferLine;

        this.findOrCreateTransferHeader(_salesLine, _metSalesLine, _salesTable, _metSalesTable);

        if(metTransferTable)
        {
            if(!METInventTransferLine::existsForSalesLine(_salesLine.InventTransId))
            {
                transferLine.initFromSalesLine(_salesLine);
                transferLine.initFromInventTransferTable(transferTable, true);

                // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
                // Need to look at deliver remainder for backorders scenario
                transferLine.QtyTransfer = (_salesLine.RemainInventPhysical - qtyReserved);

                if(_salesLine.PdsCWQty)
                {
                    transferLine.PdsCWQtyTransfer = _salesLine.pdsCWQtyActivateRemainder();
                    transferLine.modifiedField(fieldNum(InventTransferLine, PdsCWQtyTransfer));
                }

                transferLine.QtyRemainReceive = transferLine.QtyTransfer;
                transferLine.QtyRemainShip = transferLine.QtyTransfer;

                // Bug 222516: CB238 - TO creation missing Location dimension
                // Copy the SO line wMSLocationId into the transfer order line. Site/WH already set from the supplying WH in initFromInventTransferTable
                InventDim inventDim = transferLine.inventDim();
                inventDim.wMSLocationId = _salesLine.inventDim().wMSLocationId;

                transferLine.LineNum = _salesLine.LineNum;
                transferLine.InventDimId = inventDim::findOrCreate(inventDim).inventDimId;

                if(transferLine.validateWrite())
                {
                    transferLine.insert();
                }

                // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
                // Commented FC confirmed not to use preview feature
                //this.insertSupplyRelation(_salesLine, transferLine);                    
                //this.checkAndUpdateMarking(_salesLine, transferLine);

                metTransferLine.clear();
                metTransferLine.initValue();
                metTransferLine.InventTransferLine = transferLine.RecId;
                metTransferLine.SalesLineTransId = _salesLine.InventTransId;

                // 218457 - CB238 - Bug - Liquor extraction Internal Customer not getting updated - Start
                metTransferLine.SalesId = _salesTable.SalesId;
                // 218457 - CB238 - Bug - Liquor extraction Internal Customer not getting updated - End

                // Allow substitution only when,
                // 1. Metcash sales order type allows substitution
                // 2. No quantity is reserved on the origin sales line
                METSalesOrderTypes metOrderType = _salesTable.METSalesOrderTypes();
                if(metOrderType && metOrderType.SubstitutesAllowed == NoYes::Yes)
                {
                    metTransferLine.AllowSubstitution = qtyReserved == 0 ? NoYes::Yes : NoYes::No;
                }
                else
                {
                    metTransferLine.AllowSubstitution = NoYes::No;
                }

                InventMovement::bufferSetRemainQty(transferLine, InventMovSubType::None);
                InventMovement::bufferSetRemainQty(transferLine, InventMovSubType::TransferOrderTransitFrom);
                //If the Salesline order extraction status is already extracted means the transfer order line is being created as an effect of a substitution process.
                //In that case we need to set the transfer line extraction status to Ready to Extract, so the line is picked in the second pick list attempt.
                if(_metSalesLine.OrderExtractStatus == METOrderExtractStatus::Extracted)
                {
                    metTransferLine.OrderExtractStatus = METOrderExtractStatus::ReadyForExtract;
                }

                metTransferLine.insert();
                metTransferLine.updateUnitFields();

                if(metTransferLine)
                {
                    _metSalesLine.selectForUpdate(true);
                    _metSalesLine.TransferOrderNumber = transferTable.TransferId;
                    _metSalesLine.InventTransIdReceive = transferLine.InventTransIdReceive;
                    _metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;

                    _metSalesLine.update();
                }
            }
        }
    }

}

public void CreateTransferOrder(SalesTable _salesTable)
{
    SalesLine salesLine;
    METSalesLine metSalesLine;
    METSalesTable metSalesTable = METSalesTable::findByRefRecId(_salesTable.RecId);
    METSubstitutionSalesLineProcess subSalesLineProcess;
    InventDim inventDim;
    inventParameter = InventParameters::find();

    ttsbegin;
    while select salesLine
        order by metSalesLine.SupplyingWarehouse
        where salesLine.SalesId == _salesTable.SalesId &&
              salesLine.SalesStatus != SalesStatus::Canceled // 218457 - CB238 - Bug - Liquor extraction Internal Customer not getting updated
        join metSalesLine where metSalesLine.SalesLine == salesLine.RecId
        && metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted
    {
        this.CreateTransferOrderLine(salesLine, metSalesLine, _salesTable, metSalesTable);
    }

    _salesTable.metUpdateExtractStatus();

    ttscommit;

    //CB627_TMSEngineProcessingTOCreation
    METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::TransferOrderCreation, transferTable).run();
}

private void updateOrderExtractionStatus(SalesTable _salesTable)
{
    METSalesTable salesTable;
    SalesLine salesLine;
    METSalesLine metSalesLine;

    select firstonly salesLine
        where salesLine.SalesId == _salesTable.SalesId
        exists join metSalesLine
        where metSalesLine.SalesLine == salesLine.RecId
        && metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted;

    if(!salesLine)
    {
        _salesTable.reread();
        _salesTable.selectForUpdate(true);
        _salesTable.METOrderExtractStatus = METOrderExtractStatus::Extracted;
        _salesTable.METOrderExtractDateTime = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        _salesTable.update();
    }
}
